import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int k = Integer.parseInt(st.nextToken());int count = 0;for (int i = 0; i < n; i++) {String line = br.readLine();if (line == null) break;int val = Integer.parseInt(line);if (val % k == 0) {count++;}}System.out.println(count);}}